CREATE OR REPLACE FUNCTION public.rpc_ai_dispatch_need_turn_v2_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;
begin
 if p_account_id is null or p_conversation_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or t.conversation_id<>c.id or t.attempt_id is distinct from p_attempt_id
 or t.state<>'PROCESSING' or t.cancelled_at is not null or t.provider_dispatched or c.status<>'OPEN'
 or t.lease_expires_at<=clock_timestamp() or t.context_hash is distinct from (private.ai_need_turn_context(c.id)->>'sha256') then return false;end if;
 update private.ai_need_turn_commands set provider_dispatched=true,updated_at=clock_timestamp()
 where account_id=p_account_id and client_request_id=p_client_request_id;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.rpc_ai_fail_need_turn_v2_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if p_account_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 perform 1 from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 update private.ai_need_turn_commands set state='FAILED', updated_at=clock_timestamp()
 where account_id=p_account_id and client_request_id=p_client_request_id and conversation_id=p_conversation_id
 and state='PROCESSING' and attempt_id=p_attempt_id and cancelled_at is null;
 return private.ai_need_turn_status(p_account_id,p_conversation_id,p_client_request_id);
end $function$

CREATE OR REPLACE FUNCTION public.rpc_ai_test_record_usage_service(p_operation_id uuid, p_model text, p_prompt_tokens integer, p_output_tokens integer, p_total_tokens integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_reservation private.ai_test_reservations_v5;
  v_existing private.ai_test_usage_v5;
  v_cost bigint;
  v_previous bigint;
  v_released bigint;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_operation_id is null or p_model is null
     or p_prompt_tokens is null or p_output_tokens is null or p_total_tokens is null
     or p_prompt_tokens < 0 or p_output_tokens < 0 or p_total_tokens < 0 then
    raise exception 'AI_USAGE_INPUT_INVALID' using errcode = '22023';
  end if;

  -- Serialize every settlement with reservation admission before reading its
  -- current basis. A concurrent release/estimate cannot race measured usage.
  perform 1 from private.ai_test_budget_v5 where singleton for update;
  if not found then raise exception 'AI_TEST_BUDGET_NOT_READY' using errcode = '55000'; end if;

  select * into v_reservation from private.ai_test_reservations_v5
    where operation_id = p_operation_id for update;
  if not found then raise exception 'AI_USAGE_NO_RESERVATION' using errcode = '42501'; end if;

  select * into v_existing from private.ai_test_usage_v5 where operation_id = p_operation_id;
  if found then
    if v_existing.prompt_tokens = p_prompt_tokens and v_existing.output_tokens = p_output_tokens
       and v_existing.total_tokens = p_total_tokens and v_existing.model = btrim(p_model) then
      return jsonb_build_object('operationId', p_operation_id, 'recorded', false,
        'promptTokens', v_existing.prompt_tokens, 'outputTokens', v_existing.output_tokens,
        'totalTokens', v_existing.total_tokens, 'authoritative', true,
        'settledMicrousd', v_reservation.settled_microusd, 'releasedMicrousd', 0);
    end if;
    raise exception 'AI_USAGE_ALREADY_RECORDED' using errcode = '55000';
  end if;

  insert into private.ai_test_usage_v5(operation_id, account_id, model, prompt_tokens, output_tokens, total_tokens)
    values (p_operation_id, v_reservation.account_id, btrim(p_model), p_prompt_tokens, p_output_tokens, p_total_tokens);

  -- This is an internal price calculation from reported usage, not an invoice.
  -- Never truncate a known cost to the earlier estimated maximum. A late usage
  -- receipt replaces an earlier estimate or no-dispatch release exactly once.
  v_cost := private.ai_test_price_microusd(p_prompt_tokens, p_output_tokens);
  v_previous := coalesce(v_reservation.settled_microusd, v_reservation.max_cost_microusd);
  v_released := greatest(0, v_previous - v_cost);
  update private.ai_test_reservations_v5
     set settled_microusd = v_cost, settlement_basis = 'MEASURED', settled_at = statement_timestamp()
   where operation_id = p_operation_id;
  update private.ai_test_budget_v5
     set reserved_microusd = reserved_microusd + v_cost - v_previous where singleton;

  return jsonb_build_object('operationId', p_operation_id, 'recorded', true,
    'promptTokens', p_prompt_tokens, 'outputTokens', p_output_tokens,
    'totalTokens', p_total_tokens, 'authoritative', true,
    'settledMicrousd', v_cost, 'releasedMicrousd', v_released);
end
$function$

CREATE OR REPLACE FUNCTION public.rpc_claim_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s private.worker_ai_sessions; t private.worker_ai_turns; hash text; message_id uuid;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 if p_client_request_id is null or p_text is null or length(btrim(p_text)) not between 1 and 4000
 then raise exception 'WORKER_AI_INPUT_INVALID' using errcode='22023'; end if;
 hash:=encode(extensions.digest(p_text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-turn:'||p_account_id::text||p_client_request_id::text,0));
 select * into s from private.worker_ai_sessions where conversation_id=p_conversation_id and account_id=p_account_id for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 select * into t from private.worker_ai_turns where account_id=p_account_id and client_request_id=p_client_request_id;
 if found then
  if t.conversation_id<>p_conversation_id then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409'; end if;
  if t.cancelled_at is not null then return jsonb_build_object('acquired',false,'turn',private.worker_ai_turn_document(t.turn_id));end if;
  if t.body_hash<>hash then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409'; end if;
  return jsonb_build_object('acquired',false,'turn',private.worker_ai_turn_document(t.turn_id));
 end if;
 perform public.rpc_read_worker_ai_context_service(p_account_id,p_conversation_id);
 perform 1 from public.ai_conversations where id=p_conversation_id for update;
 if exists(select 1 from private.worker_ai_turns where conversation_id=p_conversation_id and state='PROCESSING')
 then raise exception 'WORKER_AI_TURN_PENDING' using errcode='55000'; end if;
 if (select count(*) from private.worker_ai_turns where account_id=p_account_id and created_at>clock_timestamp()-interval '1 minute')>=6
 then raise exception 'WORKER_AI_RATE_LIMITED' using errcode='55000'; end if;
 insert into private.worker_ai_turns(account_id,conversation_id,client_request_id,body_hash,source_revision,state,lease_expires_at)
 values(p_account_id,p_conversation_id,p_client_request_id,hash,s.revision,'PROCESSING',clock_timestamp()+interval '60 seconds') returning * into t;
 insert into public.ai_messages(account_id,conversation_id,role,body) values(p_account_id,p_conversation_id,'USER',p_text) returning id into message_id;
 update private.worker_ai_turns set user_message_id=message_id where turn_id=t.turn_id;
 return jsonb_build_object('acquired',true,'turn',private.worker_ai_turn_document(t.turn_id));
end $function$

CREATE OR REPLACE FUNCTION public.rpc_dispatch_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s private.worker_ai_sessions; t private.worker_ai_turns; parent_open boolean;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 perform private.closure_assert_open(p_account_id);
 if p_client_request_id is null or p_attempt_id is null then raise exception 'WORKER_AI_ID_REQUIRED' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-turn:'||p_account_id::text||p_client_request_id::text,0));
 select * into s from private.worker_ai_sessions where account_id=p_account_id and conversation_id=p_conversation_id for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501';end if;
 perform 1 from public.ai_conversations where id=p_conversation_id and account_id=p_account_id and purpose='PROFILE' and status='OPEN' for update;parent_open:=found;
 select * into t from private.worker_ai_turns where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or t.conversation_id is distinct from p_conversation_id or t.attempt_id is distinct from p_attempt_id then raise exception 'WORKER_AI_DENIED' using errcode='42501';end if;
 if t.state<>'PROCESSING' or t.provider_dispatched or t.cancelled_at is not null or t.lease_expires_at<=clock_timestamp()
 or t.source_revision<>s.revision or not parent_open or s.safety not in('ALLOW','CLARIFY') or s.base_hash is distinct from private.worker_ai_source_hash(p_account_id)
 then return jsonb_build_object('dispatched',false,'turn',private.worker_ai_turn_document(t.turn_id));end if;
 update private.worker_ai_turns set provider_dispatched=true where turn_id=t.turn_id;
 return jsonb_build_object('dispatched',true,'turn',private.worker_ai_turn_document(t.turn_id));
end $function$

CREATE OR REPLACE FUNCTION public.rpc_fail_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare t private.worker_ai_turns;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 select * into t from private.worker_ai_turns where account_id=p_account_id and conversation_id=p_conversation_id and client_request_id=p_client_request_id for update;
 if not found or t.attempt_id is distinct from p_attempt_id then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 if t.state='PROCESSING' and t.lease_expires_at>=clock_timestamp() then update private.worker_ai_turns set state='FAILED' where turn_id=t.turn_id; end if;
 return private.worker_ai_turn_document(t.turn_id);
end $function$

CREATE OR REPLACE FUNCTION private.ai_claim_need_turn_context_v1(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_user_message text, p_location_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;request_hash_value text;ctx jsonb;now_at timestamptz;attempt uuid;turn jsonb;
begin
 if p_account_id is null or p_conversation_id is null or p_client_request_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 if p_user_message is null or char_length(btrim(p_user_message)) not between 1 and 4000 then raise exception 'USER_MESSAGE_INVALID' using errcode='22023';end if;
 if p_location_context is not null and not private.ai_location_context_valid(p_location_context) then raise exception 'LOCATION_CONTEXT_INVALID' using errcode='PT409';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 now_at:=clock_timestamp();
 request_hash_value:=private.ai_location_request_hash(c.id,p_user_message,p_location_context);
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if found and t.conversation_id<>c.id then raise exception 'AI_REQUEST_ID_REUSED' using errcode=case when p_location_context is null then '22023' else 'PT409' end;end if;
 if t.cancelled_at is not null then
  if t.request_hash<>repeat('0',64) and t.request_hash<>request_hash_value then raise exception 'AI_REQUEST_ID_REUSED' using errcode=case when p_location_context is null then '22023' else 'PT409' end;end if;
  return jsonb_build_object('turn',private.ai_need_turn_status(p_account_id,c.id,p_client_request_id),'claim',null);
 end if;
 if found and (t.conversation_id<>c.id or t.request_hash<>request_hash_value) then raise exception 'AI_REQUEST_ID_REUSED' using errcode=case when p_location_context is null then '22023' else 'PT409' end;end if;
 turn:=private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);
 if not (turn->>'retryAllowed')::boolean then
  if t.turn_id is null then
   insert into private.ai_need_turn_commands(account_id,client_request_id,conversation_id,request_hash,state)
   values(p_account_id,p_client_request_id,c.id,request_hash_value,'FAILED');
   turn:=private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);
  end if;
  return jsonb_build_object('turn',turn,'claim',null);
 end if;
 if (select count(*) from private.ai_need_turn_commands x cross join lateral unnest(x.attempt_times) a(started)
  where x.account_id=p_account_id and a.started>now_at-interval '1 minute')>=6
 then raise exception 'AI_RATE_LIMITED' using errcode='P0001';end if;
 if p_location_context is not null and not private.ai_location_review_matches(c.id,p_location_context) then raise exception 'LOCATION_VERSION_CONFLICT' using errcode='PT409';end if;
 ctx:=private.ai_need_turn_context(c.id);attempt:=gen_random_uuid();
 if t.turn_id is null then
  insert into private.ai_need_turn_commands(account_id,client_request_id,conversation_id,request_hash,state,context_hash,attempt_id,lease_expires_at,attempt_times)
  values(p_account_id,p_client_request_id,c.id,request_hash_value,'PROCESSING',ctx->>'sha256',attempt,now_at+interval '90 seconds',array[now_at]);
 else
  update private.ai_need_turn_commands set state='PROCESSING',context_hash=ctx->>'sha256',attempt_id=attempt,
   lease_expires_at=now_at+interval '90 seconds',updated_at=now_at,
   attempt_times=array(select x from unnest(attempt_times) x where x>now_at-interval '1 minute')||array[now_at]
  where account_id=p_account_id and client_request_id=p_client_request_id;
 end if;
 return jsonb_build_object('turn',private.ai_need_turn_status(p_account_id,c.id,p_client_request_id),
  'claim',jsonb_build_object('attemptId',attempt,'leaseExpiresAt',now_at+interval '90 seconds','context',ctx->'context'));
end $function$

CREATE OR REPLACE FUNCTION private.ai_need_turn_context(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;history jsonb;facts jsonb;provider_facts jsonb;binding jsonb;material jsonb;
begin
 select * into c from public.ai_conversations where id=p_conversation_id;
 if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 select coalesce(jsonb_agg(to_jsonb(m) order by m.sequence_no),'[]'::jsonb) into history from
  (select id,role,body,safety,sequence_no from public.ai_messages where conversation_id=c.id order by sequence_no desc limit 40) m;
 select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'fact_key',f.fact_key,'fact_value',f.fact_value,
  'value_type',f.value_type,'display_value',f.display_value,'fact_schema_version',f.fact_schema_version,
  'status',f.status,'source',f.source,'created_at',f.created_at) order by f.created_at,f.id),'[]'::jsonb)
 into facts from public.ai_structured_facts f where f.conversation_id=c.id and f.superseded_at is null;
 if jsonb_array_length(facts)>64 then raise exception 'AI_CONTEXT_TOO_LARGE' using errcode='22001';end if;
 binding:=jsonb_build_object('conversationId',c.id,'accountId',c.account_id,'status',c.status,
  'boundNeedId',c.bound_need_id,'schema',c.fact_schema_version,'editBase',c.need_edit_base_fingerprint);
 material:=jsonb_build_object('binding',binding,'history',history,'facts',facts);
 if octet_length(material::text)>524288 then raise exception 'AI_CONTEXT_TOO_LARGE' using errcode='22001';end if;
 -- The full material hash fences manual edits, but the private witness never
 -- leaves SQL. Only the current AI-proposable registry reaches the provider.
 select coalesce(jsonb_agg(f.value-'id' order by f.ordinality),'[]'::jsonb) into provider_facts
 from jsonb_array_elements(facts) with ordinality f(value,ordinality)
 join private.need_fact_registry r on r.fact_key=f.value->>'fact_key'
 where f.value->>'fact_key' not in('need.resolved_location','need.public_photo_paths','need.verified_identity_required');
 return jsonb_build_object('sha256',encode(extensions.digest(convert_to(material::text,'UTF8'),'sha256'),'hex'),
  'context',jsonb_build_object('schemaVersion','NEED_FACT_V2',
  'history',(select coalesce(jsonb_agg(h.value-'id'-'safety' order by h.position),'[]'::jsonb) from jsonb_array_elements(history) with ordinality h(value,position)),
  'activeFacts',provider_facts));
end $function$

CREATE OR REPLACE FUNCTION public.rpc_read_worker_ai_context_service(p_account_id uuid, p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare doc jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from private.worker_ai_sessions where conversation_id=p_conversation_id and account_id=p_account_id)
 then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 doc:=private.worker_ai_document(p_conversation_id);
 if doc is null or doc->>'status'<>'OPEN' or doc->>'safety' in ('BLOCK','REVIEW') or doc->'stale'='true'::jsonb then raise exception 'WORKER_AI_NOT_EDITABLE' using errcode='55000'; end if;
 -- Keep owned history intact. Only the exact USER message attached by a new
 -- claim and subsequently cancelled before dispatch is excluded from provider
 -- context. Legacy rows have no fabricated timestamp-based association.
 return jsonb_set(doc-array['review','saved'],'{messages}',coalesce((
  select jsonb_agg(m.value order by m.ordinality) from jsonb_array_elements(doc->'messages') with ordinality m(value,ordinality)
  where not exists(select 1 from private.worker_ai_turns t where t.account_id=p_account_id and t.conversation_id=p_conversation_id
   and t.cancelled_at is not null and t.user_message_id=(m.value->>'id')::uuid)), '[]'::jsonb)) || jsonb_build_object('serviceModeContext',
   private.worker_ai_service_mode_context_v1(p_account_id,p_conversation_id));
end $function$

CREATE OR REPLACE FUNCTION private.ai_need_turn_status(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;ready boolean;state_value text;
begin
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for share;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2'
 then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 if p_client_request_id is null then raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';end if;
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id;
 if found and t.conversation_id<>c.id then raise exception 'AI_REQUEST_ID_REUSED' using errcode='22023';end if;
 ready:=c.status='OPEN' and not exists(select 1 from private.ai_need_turn_commands x where x.conversation_id=c.id
  and x.client_request_id<>p_client_request_id and x.state='PROCESSING' and (x.lease_expires_at is null or x.lease_expires_at > clock_timestamp()));
 state_value:=case when t.turn_id is null then 'ABSENT' else t.state end;
 return jsonb_build_object('conversationId',c.id,'clientRequestId',p_client_request_id,'state',state_value,'turnId',t.turn_id,
  'retryAllowed',ready and (state_value='ABSENT' or (state_value='FAILED' and not t.provider_dispatched and t.cancelled_at is null)),
  'receipt',t.receipt-'location');
end $function$

CREATE OR REPLACE FUNCTION public.rpc_ai_test_budget_reserve_service(p_account_id uuid, p_operation_id uuid, p_kind text, p_max_cost_microusd bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_budget private.ai_test_budget_v5%rowtype;
  v_existing private.ai_test_reservations_v5%rowtype;
  v_id uuid;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_account_id is null or p_operation_id is null or p_kind not in ('LLM','STT') or p_kind is null
    or p_max_cost_microusd is distinct from (case p_kind when 'LLM' then 250000::bigint when 'STT' then 200000::bigint end) then
    raise exception 'AI_TEST_RESERVATION_INVALID';
  end if;

  -- Match existing closure ordering before the global budget row. A closing
  -- account cannot acquire a fresh provider operation.
  perform pg_advisory_xact_lock_shared(private.closure_account_key(p_account_id));
  -- Every reservation shares this row, so different accounts cannot each spend $5.
  select * into strict v_budget from private.ai_test_budget_v5 where singleton for update;
  select * into v_existing from private.ai_test_reservations_v5 where operation_id = p_operation_id;
  if found then
    if v_existing.account_id <> p_account_id or v_existing.kind <> p_kind
      or v_existing.max_cost_microusd <> p_max_cost_microusd then
      raise exception 'AI_TEST_OPERATION_CONFLICT';
    end if;
    -- Admission is deliberately false: a retry may read its existing receipt but cannot call a provider again.
    return jsonb_build_object('admitted',false,'reservationId',v_existing.id,'replay',true,'code','AI_TEST_OPERATION_REPLAY');
  end if;

  if not v_budget.enabled or not v_budget.reservation_cap_enforced
    or statement_timestamp() >= v_budget.price_valid_until then
    return jsonb_build_object('admitted',false,'reservationId',null,'replay',false,'code','AI_TEST_BUDGET_NOT_READY');
  end if;
  if not exists(select 1 from private.ai_test_accounts_v5 where account_id=p_account_id and retired_at is null)
    or not exists(select 1 from auth.users where id=p_account_id and deleted_at is null)
    or private.closure_account_restricted(p_account_id) then
    return jsonb_build_object('admitted',false,'reservationId',null,'replay',false,'code','AI_TEST_ACCOUNT_NOT_ADMITTED');
  end if;
  if v_budget.reserved_microusd + p_max_cost_microusd > v_budget.ceiling_microusd then
    return jsonb_build_object('admitted',false,'reservationId',null,'replay',false,'code','AI_TEST_BUDGET_EXHAUSTED');
  end if;

  insert into private.ai_test_reservations_v5(operation_id,account_id,kind,max_cost_microusd)
    values(p_operation_id,p_account_id,p_kind,p_max_cost_microusd) returning id into v_id;
  update private.ai_test_budget_v5 set reserved_microusd=reserved_microusd+p_max_cost_microusd where singleton;
  return jsonb_build_object('admitted',true,'reservationId',v_id,'replay',false,'code','AI_TEST_RESERVED');
end
$function$

CREATE OR REPLACE FUNCTION private.ai_location_context_valid(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb;a jsonb;
begin
 if v is null or jsonb_typeof(v)<>'object' or octet_length(v::text)>40000
 or (select count(*) from jsonb_object_keys(v))<>9
 or not(v ?& array['version','promptToken','reviewRevision','slot','phase','question','query','proposal','alternatives'])
 or v->'version'<>'1'::jsonb
 or jsonb_typeof(v->'promptToken')<>'string' or v->>'promptToken'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 or jsonb_typeof(v->'reviewRevision')<>'string' or v->>'reviewRevision'!~'^[0-9a-f]{64}$'
 or jsonb_typeof(v->'slot')<>'string' or v->>'slot'!~'^(start|end|serviceArea|waypoints/([0-9]|1[0-9]))$'
 or jsonb_typeof(v->'phase') is distinct from 'string' or coalesce(v->>'phase','') not in('PROPOSAL','AMBIGUOUS','UNRESOLVED')
 or jsonb_typeof(v->'question')<>'string' or char_length(btrim(v->>'question')) not between 1 and 300
 or jsonb_typeof(v->'query')<>'string' or char_length(v->>'query')>1000
 or jsonb_typeof(v->'alternatives')<>'array' or jsonb_array_length(v->'alternatives')>20 then return false;end if;
 p:=v->'proposal';
 if (v->>'phase'='PROPOSAL') is distinct from (p<>'null'::jsonb) then return false;end if;
 if p<>'null'::jsonb and (jsonb_typeof(p)<>'object' or (select count(*) from jsonb_object_keys(p))<>2
 or not(p ?& array['id','label']) or jsonb_typeof(p->'id')<>'string'
 or p->>'id'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 or jsonb_typeof(p->'label')<>'string' or char_length(btrim(p->>'label')) not between 1 and 1000) then return false;end if;
 if v->>'phase'='AMBIGUOUS' and jsonb_array_length(v->'alternatives')<2
 or v->>'phase'='UNRESOLVED' and jsonb_array_length(v->'alternatives')<>0 then return false;end if;
 for a in select value from jsonb_array_elements(v->'alternatives') loop
  if jsonb_typeof(a)<>'object' or (select count(*) from jsonb_object_keys(a))<>2 or not(a ?& array['id','label'])
  or jsonb_typeof(a->'id')<>'string' or char_length(btrim(a->>'id')) not between 1 and 160
  or jsonb_typeof(a->'label')<>'string' or char_length(btrim(a->>'label')) not between 1 and 1000 then return false;end if;
 end loop;
 return (select count(*)=count(distinct value->>'id') from jsonb_array_elements(v->'alternatives'));
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION private.ai_turn_sweep_v5(p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_cutoff timestamptz := coalesce(p_at, statement_timestamp()) - interval '10 minutes';
  v_need integer := 0; v_worker integer := 0; v_qa integer := 0; v_review integer := 0; v_errors jsonb := '[]'::jsonb;
begin
  -- A turn whose lease ended ten minutes ago will never be completed by the worker that claimed it.
  -- Expiry is still not proof that the provider did not run, so the request itself is never retried:
  -- it stays failed, and only a NEW request from the person can continue the conversation. What changes
  -- is that it stops blocking that conversation and the account's closure forever.
  begin
    update private.ai_need_turn_commands set state = 'FAILED', updated_at = clock_timestamp()
     where state = 'PROCESSING' and lease_expires_at < v_cutoff;
    get diagnostics v_need = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'NEED_INTAKE', 'sqlstate', sqlstate));
  end;
  begin
    update private.worker_ai_turns set state = 'FAILED'
     where state = 'PROCESSING' and lease_expires_at < v_cutoff;
    get diagnostics v_worker = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'WORKER_PROFILE', 'sqlstate', sqlstate));
  end;
  begin
    -- CANCELLED is the existing "this send will never publish anything" state the app already explains.
    update private.qa_ai_commands set state = 'CANCELLED', updated_at = clock_timestamp()
     where state = 'PROCESSING' and lease_expires_at < v_cutoff
       and not private.closure_account_restricted(account_id);
    get diagnostics v_qa = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'PRESELECTION_QA', 'sqlstate', sqlstate));
  end;
  -- PKG-037: a publication claim cannot complete after its 60-second lease.
  -- End expired attempts without a decision, another paid request or any refund.
  -- Lock only a bounded batch; an in-flight completion wins or is fenced by state.
  begin
    with expired as (
      select c.review_id from private.ai_task_review_commands c
       where c.state = 'EVALUATING'
         and c.lease_expires_at <= least(coalesce(p_at, statement_timestamp()), clock_timestamp())
       order by c.lease_expires_at, c.review_id limit 100 for update skip locked
    )
    update private.ai_task_review_commands c set state = 'EVALUATED',
      evaluation = jsonb_build_object('kind','NOT_READY','needId',c.need_id,
        'needRevision',c.need_revision,'authoritativeDecision',false,'code','EVALUATOR_UNAVAILABLE'),
      evaluation_result_hash = encode(extensions.digest(jsonb_build_object(
        'outcome',null,'rules','[]'::jsonb,'reasons','[]'::jsonb,'provider',null,'model',null,
        'notReady','EVALUATOR_UNAVAILABLE')::text,'sha256'),'hex')
     where c.review_id in (select review_id from expired) and c.state = 'EVALUATING';
    get diagnostics v_review = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns','PUBLICATION_REVIEW','sqlstate',sqlstate));
  end;
  return jsonb_build_object('needTurnsFailed', v_need, 'workerTurnsFailed', v_worker,
    'qaCommandsCancelled', v_qa, 'reviewEvaluationsStopped', v_review, 'graceMinutes', 10, 'errors', v_errors);
end
$function$

CREATE OR REPLACE FUNCTION private.closure_assert_open(a uuid, b uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid;
begin
 if a is null then raise exception 'CLOSURE_CONTEXT_INVALID' using errcode='42501'; end if;
 for u in select distinct x from unnest(array[a,b]) x where x is not null order by x loop
  perform pg_advisory_xact_lock_shared(private.closure_account_key(u));
  if private.closure_account_restricted(u) then raise exception 'ACCOUNT_CLOSING' using errcode='42501'; end if;
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.closure_redaction_allowed_v5(rel oid, op text, before_row jsonb, after_row jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c private.closure_redaction_certificate_v5;keys text[];
begin
 if auth.role() is distinct from 'service_role' or rel is null or op is null or op not in('UPDATE','DELETE') or before_row is null then return false;end if;
 select * into c from private.closure_redaction_certificate_v5 where backend_pid=pg_backend_pid() and transaction_id=txid_current();
 if not found or c.relation_oid<>rel or c.operation<>op
 or c.old_sha256 is distinct from encode(extensions.digest(convert_to(before_row::text,'UTF8'),'sha256'),'hex')
 or not exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 a on a.generation=e.generation and a.account_id=e.account_id
  where e.account_id=c.account_id and e.generation=c.generation and e.state='EXECUTING'
   and e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1'
   and a.id=c.action_id and a.kind='RELATIONAL_REDACT' and a.state='DISPATCHED') then return false;end if;
 if op='DELETE' then return after_row is null and c.patch='{}'::jsonb;end if;
 select coalesce(array_agg(k),'{}') into keys from jsonb_object_keys(c.patch) k;
 -- This one generated column is derived from the two erased coordinates. Its
 -- BEFORE value is not materialized yet; executor verifies final NULL afterward.
 if rel='public.needs'::regclass and c.patch@>'{"approximate_lat":null,"approximate_lng":null}'::jsonb then keys:=keys||array['approx_geog'];end if;
 return after_row is not null and after_row@>c.patch
  and (after_row-keys-array['updated_at']) is not distinct from (before_row-keys-array['updated_at']);
end $function$

CREATE OR REPLACE FUNCTION private.closure_redaction_patch_v5(r text, t jsonb, a uuid, g uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb:='{}';k text;h text;ag public.agreements;terms jsonb;
begin
 if r is null or t is null or a is null or g is null or not(r=any(private.closure_redaction_relations_v5()))
 then raise exception 'ERASURE_RELATION_NOT_ADMITTED';end if;
 if r=ANY(ARRAY['private.work_taxonomy_review_outbox_v1','private.work_taxonomy_pending_reviews_v1','private.work_taxonomy_gemini_turn_hints_v1','private.work_taxonomy_admissions_v1','private.work_taxonomy_review_batches_v1','private.work_taxonomy_related_acceptances','private.taxonomy_confirmed_worker_modes_v1','private.work_taxonomy_worker_capabilities','private.worker_execution_mode_choices','private.work_taxonomy_need_skills','private.work_taxonomy_need_snapshots','private.work_taxonomy_need_bindings_v1','private.work_taxonomy_worker_bindings_v1','private.dev_phase1_20261014_worker_capabilities_snapshot','private.dev_phase1_20261014_opportunity_snapshot','private.dev_phase1_20261014_dispatch_snapshot','private.dev_test101_owner_worker_profile_backup','private.dev_test101_owner_profile_backup_20261014','private.dev_worker_profile_reset_snapshots_v1','private.dev_phase1_20261014_needs_snapshot']::text[]) then return private.closure_taxonomy_patch_v1(r,t,a,g);end if;
 if r='public.agreement_invalidations_v1' then
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
 h:=encode(extensions.digest(convert_to('AF-D22:ERASED:'||r||':'||coalesce(t->>'id',t->>'client_request_id',t->>'conversation_id',t->>'review_id',t->>'account_id','subject'),'UTF8'),'sha256'),'hex');
 -- Support command receipts are metadata only. A related scoped case keeps its
 -- exact recovery/hash contract until that exception is resolved; no narrative
 -- is copied into the redaction ledger. Cancelled opaque tombstones stay usable.
 if r in('private.support_commands_v5','private.support_grant_commands_v5') then return null;end if;
 if r in('public.ai_conversations','public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.worker_ai_sessions','private.ai_task_reviews','private.worker_ai_reviews','private.need_draft_save_commands')
 and exists(select 1 from private.retention_holds where account_id=a and active and conversation_id=
  case when r='public.ai_conversations' then (t->>'id')::uuid else (t->>'conversation_id')::uuid end) then return null;end if;
 if r='private.ai_task_review_commands' and exists(select 1 from private.ai_task_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='private.worker_ai_saves' and exists(select 1 from private.worker_ai_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='public.ai_structured_facts' then
  if t->'superseded_by'<>'null'::jsonb then return jsonb_build_object('operation','UPDATE','patch',jsonb_build_object('superseded_by',null));end if;
  if exists(select 1 from public.ai_structured_facts where superseded_by=(t->>'id')::uuid) then return null;end if;
 end if;
 if r in('public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'public.need_sensitive','public.need_geography','public.need_requirement_details',
  'private.data_export_artifacts','public.notification_push_attempts','public.notification_deliveries',
  'public.notification_push_devices','public.notification_preferences','public.opportunity_deliveries',
  'private.dispatch_schedule','public.access_grants','public.profile_availability_rules','public.profile_availability_windows',
  'public.worker_match_preferences','private.worker_calendar_events','private.worker_calendar_serialization',
  'private.support_read_markers_v5','private.group_message_visibility_v5','private.agreement_review_comments_v1') then
  if r='private.data_export_artifacts' and exists(select 1 from storage.objects where bucket_id='data-export-artifacts' and name=t->>'object_path')
  then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='private.agreement_voice_uploads_v1' then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if exists(select 1 from storage.objects where bucket_id='agreement-voice' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r in('private.owned_media_assets','private.agreement_photo_uploads_v5') then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if private.closure_erasure_media_protected_v5(a,t->>'storage_path') then return null;end if;
  if exists(select 1 from storage.objects where bucket_id='profile-media' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='public.app_accounts' then p:=jsonb_build_object('email','','phone','','full_name','','city','');
 elsif r='public.app_profiles' then p:=jsonb_build_object('display_name','','city','','headline','','bio','','avatar_path',null,
  'portfolio','[]'::jsonb,'skills','[]'::jsonb,'tools','[]'::jsonb,'licenses','[]'::jsonb,'vehicles','[]'::jsonb,'exclusions','[]'::jsonb,
  'years_experience',0,'radius_km',1,'available_now',false,'available_now_expires_at',null,'team_capacity',1,
  'minimum_fee_rsd',0,'rating_requester',null,'rating_worker',null,'operating_country_code',null,'profile_status','CLOSED',
  'worker_dispatch_eligible_since',null,'worker_dispatch_clock_source',null);
 elsif r='public.needs' then p:=jsonb_build_object('title','Obrisan zadatak','description','Sadržaj uklonjen pri zatvaranju naloga.','category','OBRISANO',
  'approximate_city','','approximate_area','','approximate_lat',null,'approximate_lng',null,
  'starts_at',null,'ends_at',null,'required_skills','[]'::jsonb,'required_tools','[]'::jsonb,'required_vehicles','[]'::jsonb,'required_licenses','[]'::jsonb,
  'public_photo_paths','[]'::jsonb,'requester_price_rsd',null,'response_deadline',null,'urgent',false,
  'urgent_activated_at',null,'urgent_expires_at',null,'urgent_policy_version',null,'remaining_search_close_reason',null);
 elsif r in('private.ai_task_reviews','private.worker_ai_reviews') then p:=jsonb_build_object('envelope',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.worker_ai_sessions' then p:=jsonb_build_object('candidate',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.ai_task_review_commands' then
  foreach k in array array['evaluation_binding','evaluation','published'] loop
   if t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 elsif r='private.need_revision_events' then p:=jsonb_build_object('previous_material_snapshot',jsonb_build_object('erasedBy','AF-D22'),'new_material_snapshot',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='public.data_export_requests' then p:=jsonb_build_object('active_export_attempt_id',null,
  'export_revoked_at',coalesce(nullif(t->'export_revoked_at','null'::jsonb),to_jsonb((select requested_at from private.closure_executions_v5 where generation=g and account_id=a))));
 elsif r='private.need_publication_decisions' then p:=jsonb_build_object('public_geography_snapshot',jsonb_build_object('erasedBy','AF-D22'),'public_media_refs','[]'::jsonb,'reviewer_provenance','{}'::jsonb,'service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.preselection_qa_questions' then p:=jsonb_build_object('question_text','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r='private.preselection_qa_answer_versions' then p:=jsonb_build_object('answer_text','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r in('private.preselection_qa_policy_decisions','private.preselection_qa_materiality_decisions') then
  if exists(select 1 from private.qa_ai_commands q where q.account_id<>a and
   (case when r='private.preselection_qa_policy_decisions' then q.policy_decision_id else q.materiality_decision_id end)=(t->>'id')::uuid
   and not exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 ac on ac.generation=e.generation
    where e.account_id=q.account_id and ac.kind='RELATIONAL_REDACT' and ac.state='VERIFIED')) then return null;end if;
  p:=jsonb_build_object('service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.response_application_snapshots' then p:=jsonb_build_object('worker_skills','[]'::jsonb,'worker_tools','[]'::jsonb,'worker_licenses','[]'::jsonb,'worker_vehicles','[]'::jsonb);
 elsif r in('public.marketplace_responses','public.marketplace_response_versions') then
  if exists(select 1 from public.agreements x where x.selected_response_id=coalesce(t->>'response_id',t->>'id')::uuid and private.closure_erasure_agreement_protected_v5(x.id)) then return null;end if;
  p:=jsonb_build_object('scope_note','');if t?'bounded_message' then p:=p||jsonb_build_object('bounded_message','');end if;
 elsif r='public.agreement_messages' then
  -- A selected Support copy survives in its immutable scoped snapshot. The
  -- original ordinary chat row does not need the same plaintext forever.
  p:=jsonb_build_object('body','Sadržaj uklonjen pri zatvaranju naloga.','photo_asset_ids','[]'::jsonb,'voice_asset_id',null);
 elsif r='private.group_messages_v5' then p:=jsonb_build_object('body','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r in('public.agreement_versions','public.agreement_change_proposals') then
  if private.closure_erasure_agreement_protected_v5((t->>'agreement_id')::uuid) then return null;end if;
  k:=case when r='public.agreement_versions' then 'terms' else 'proposed_terms' end;
  if exists(select 1 from private.closure_scope_sources_v5 where account_id=a and generation=g and agreement_id=(t->>'agreement_id')::uuid
   and source_kind=case when r='public.agreement_versions' then 'VERSION' else 'PROPOSAL' end
   and source_id=case when r='public.agreement_versions' then t->>'version' else t->>'id' end and scope_author=a) then
   terms:=(t->k)||jsonb_build_object('scope_note','');p:=jsonb_build_object(k,terms);
  end if;
  if r='public.agreement_change_proposals' and t->>'proposed_by_account_id'=a::text then p:=p||jsonb_build_object('reason','Sadržaj uklonjen pri zatvaranju naloga.');end if;
  if p='{}'::jsonb then return null;end if;
 elsif r='public.agreement_execution' then
  -- The source problem itself is an unresolved evidence exception.
  if t->'problem_opened_at'<>'null'::jsonb then return null;end if;
  p:=jsonb_build_object('problem_narrative',null);
 elsif r='private.agreement_location_points' then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 elsif r='public.user_activity_events' then
  if t->>'recipient_user_id'=a::text then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
  p:=jsonb_build_object('payload',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.marketplace_audit_log' then p:=jsonb_build_object('detail',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.retention_holds' then
  if t->'active'='true'::jsonb then return null;end if;
  p:=jsonb_build_object('hold_key','AF-D22:'||(t->>'id'));
 elsif r='private.ai_test_accounts_v5' then
  if t->'retired_at'='null'::jsonb then p:=jsonb_build_object('retired_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 elsif r='private.support_operator_grants_v5' then
  if t->'active'='true'::jsonb then p:=jsonb_build_object('active',false,'revision',(t->>'revision')::integer+1,'updated_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 end if;
 -- Content-derived request hashes are no longer original-content proofs after
 -- erasure. Policy/document/source-program digests and charged units are kept.
 foreach k in array array['request_hash','input_hash','input_sha256','text_sha256','semantic_hash','content_fingerprint',
  'question_fingerprint','answer_fingerprint','context_hash','body_hash','body_sha256','completion_hash','source_hash','base_hash',
  'canonical_fingerprint','private_materiality_marker','content_hash','evaluation_result_hash','need_edit_base_fingerprint'] loop
  if t?k and jsonb_typeof(t->k)='string' then p:=p||jsonb_build_object(k,h);end if;
 end loop;
 -- These JSON command results are private source copies, not immutable legal
 -- terms. Keep identity/state columns for anti-replay, never old narrative JSON.
 if r in('private.requester_identity_commands','private.worker_ai_saves','private.need_draft_save_commands',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.qa_ai_commands',
  'private.need_edit_commands','private.need_publish_commands','private.response_submit_commands','private.response_withdraw_commands',
  'private.response_revision_resolution_commands','private.remaining_search_close_commands','private.preselection_qa_commands',
  'private.account_block_commands','private.retention_jobs','private.support_commands_v5','private.support_grant_commands_v5') then
  foreach k in array array['receipt','result'] loop
   if t?k and t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 end if;
 -- An operator's note about a person is not audit metadata the subject must live with. The
 -- lineage class, its revision and its timestamps stay; the free text becomes a fixed code.
 if r in('private.account_lineage_v5','private.account_lineage_events_v5') then
  p:=p||jsonb_build_object('reason','CLOSURE_ERASED_OPERATOR_NOTE','source_ref','CLOSURE_ERASED_SOURCE_REF');
 end if;
 if r='public.needs' then p:=p||jsonb_build_object('category_id',null);end if;
 if p='{}'::jsonb or t@>p then return null;end if;
 return jsonb_build_object('operation','UPDATE','patch',p);
end $function$

